document.addEventListener("DOMContentLoaded",(function(){const e=document.getElementById("test-color-picker"),t=document.getElementById("test-color-text");e.addEventListener("input",(function(){t.value=e.value})),t.addEventListener("input",(function(){e.value=t.value}))})),document.getElementById("btn-test-send").addEventListener("click",(async function(){const e=document.getElementById("test-color-text"),t=document.getElementById("test-output"),o=new URLSearchParams;o.append("color",e.value),o.append("output",t.value);try{(await fetch("/api/color",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:o.toString()})).ok||console.error("Failed to test color")}catch(e){console.error("Error sending test color:",e)}})),document.getElementById("btn-test-off").addEventListener("click",(async function(){const e=document.getElementById("test-output"),t=new URLSearchParams;t.append("turnoff",!0),t.append("output",e.value);try{(await fetch("/api/color",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:t.toString()})).ok||console.error("Failed to turn off")}catch(e){console.error("Error sending turn off:",e)}})),document.getElementById("btn-rainbow").addEventListener("click",(async function(){const e=document.getElementById("test-output"),t=new URLSearchParams;t.append("rainbow",!0),t.append("output",e.value);try{(await fetch("/api/color",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:t.toString()})).ok||console.error("Failed to rainbow")}catch(e){console.error("Error sending rainbow:",e)}}));